11	// RMSNorm op_host — tiling calculation + strategy dispatch + EXEC_KERNEL_CMD launch
12	// Format: Abs-style with platform_ascendc and EXEC_KERNEL_CMD
13	
14	#include <algorithm>
15	#include <cstdint>
16	
17	#include <torch/extension.h>
18	#include <torch/library.h>
19	
20	#include "torch_kernel_helper.h"
21	#include "tiling/platform/platform_ascendc.h"
22	
23	#include "aclrtlaunch_rms_norm_merge_n.h"
24	#include "aclrtlaunch_rms_norm_single_row.h"
25	#include "aclrtlaunch_rms_norm_splitd.h"
26	
27	// ---------------------------------------------------------------------------
28	// Tiling constants
29	// ---------------------------------------------------------------------------
30	
31	constexpr int32_t DEFAULT_BLOCK_M = 64;
32	constexpr int32_t DEFAULT_ROW_FACTOR = 8;
33	
34	// ---------------------------------------------------------------------------
35	// Host function
36	// ---------------------------------------------------------------------------
37	
38	namespace ascend_kernel {
39	
40	std::vector<at::Tensor> rms_norm(const at::Tensor &x, const at::Tensor &gamma, double eps)
41	{
42	    TORCH_CHECK(x.dim() == 2, "x must be [M, N]");
43	    TORCH_CHECK(gamma.dim() == 1, "gamma must be [N]");
44	    TORCH_CHECK(
45	        x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
46	            x.scalar_type() == at::kBFloat16,
47	        "x must be float16, float32, or bfloat16");
48	    TORCH_CHECK(gamma.scalar_type() == x.scalar_type(),
49	        "gamma must have the same dtype as x");
50	    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
51	    TORCH_CHECK(gamma.is_contiguous(), "gamma must be contiguous");
52	    TORCH_CHECK(static_cast<int32_t>(x.sizes()[1]) == static_cast<int32_t>(gamma.sizes()[0]),
53	        "gamma shape mismatch");
54	
55	    int32_t M = static_cast<int32_t>(x.sizes()[0]);
56	    int32_t N = static_cast<int32_t>(x.sizes()[1]);
57	
58	    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
59	    int32_t aivCoreNum = static_cast<int32_t>(
60	        platform_ascendc::PlatformAscendCManager::GetInstance()->GetCoreNumAiv());
61	    if (aivCoreNum <= 0) { aivCoreNum = DEFAULT_NUM_PHYSICAL_CORES; }  // fallback
62	    int32_t usedCoreNum = std::min<int32_t>(aivCoreNum, std::max<int32_t>(1, mNum));
63	    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;
64	
65	    at::Tensor y = at::empty_like(x);
66	    at::Tensor invRms = at::empty({M}, x.options());
67	
68	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
69	    int64_t dtypeFlag = 0;
70	    if (x.scalar_type() == at::kHalf) {
71	        dtypeFlag = 1;
72	    } else if (x.scalar_type() == at::kBFloat16) {
73	        dtypeFlag = 2;
74	    }
75	
76	    // All tiling params as left values (required by EXEC_KERNEL_CMD)
77	    int32_t blockM = DEFAULT_BLOCK_M;
78	    int32_t rowFactor = DEFAULT_ROW_FACTOR;
79	    float epsVal = static_cast<float>(eps);
80	    float invN = 1.0f / static_cast<float>(N);
81	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
82	
83	    // Strategy dispatch: select kernel name and params
84	    if (N <= 1024) {
85	        EXEC_KERNEL_CMD(rms_norm_merge_n, blockDim,
86	                        x, gamma, y, invRms,
87	                        M, N, blockM, usedCoreNum, tasksPerCore, rowFactor, epsVal, invN,
88	                        dtypeFlag);
89	    } else if (N > 8192) {
90	        EXEC_KERNEL_CMD(rms_norm_splitd, blockDim,
91	                        x, gamma, y, invRms,
92	                        M, N, blockM, usedCoreNum, tasksPerCore, epsVal, invN,
93	                        dtypeFlag);
94	    } else {
95	        EXEC_KERNEL_CMD(rms_norm_single_row, blockDim,
96	                        x, gamma, y, invRms,
97	                        M, N, blockM, usedCoreNum, tasksPerCore, epsVal, invN,
98	                        dtypeFlag);
99	    }
100	
101	    return {y, invRms};
102	}
103	
104	}  // namespace ascend_kernel
