470	// =========================================================================
471	// Strategy 2: single_row — preferred when 1024 < N <= 8192
472	// =========================================================================
473	
474	template <typename dataType>
475	class RmsNormSingleRowKernel : public RmsNormKernelBase<dataType> {
476	public:
477	    __aicore__ inline void Init(
478	        GM_ADDR x, GM_ADDR gamma, GM_ADDR y, GM_ADDR invRms,
479	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
480	        int32_t tasksPerCore, float eps, float invN)
481	    {
482	        this->InitBase(x, gamma, y, invRms, M, N, blockM, usedCoreNum, tasksPerCore, eps, invN);
483	
484	        if ASCEND_IS_AIV {
485	            this->subBlockRows_ = blockM / AscendC::GetSubBlockNum();
486	            this->pipe.InitBuffer(gammaBuf_, N * sizeof(dataType));
487	            this->pipe.InitBuffer(xInQueue_, BUFFER_NUM, N * sizeof(dataType));
488	            this->pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N * sizeof(dataType));
489	            this->pipe.InitBuffer(invRmsOutQueue_, BUFFER_NUM, sizeof(dataType));
490	            this->pipe.InitBuffer(reduceBuf_, N * sizeof(float));
491	            this->pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
492	            this->pipe.InitBuffer(invRmsBuf_, sizeof(float));
493	            if constexpr (!std::is_same_v<dataType, float>) {
494	                this->pipe.InitBuffer(xCastBuf_, N * sizeof(float));
495	                this->pipe.InitBuffer(gammaCastBuf_, N * sizeof(float));
496	                this->pipe.InitBuffer(yCastBuf_, N * sizeof(float));
497	            }
498	
499	            gammaInLocal_ = gammaBuf_.Get<dataType>();
500	            LoadGmToUb(gammaInLocal_, this->gammaGM_, static_cast<uint32_t>(N));
501	            AscendC::PipeBarrier<PIPE_MTE2>();
502	            AscendC::PipeBarrier<PIPE_ALL>();
503	            PrepareInputTensorHelper<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, N);
504	        }
505	    }
506	
507	    __aicore__ inline void Process()
508	    {
509	        if ASCEND_IS_AIV {
510	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
511	            const int subBlockIdx = AscendC::GetSubBlockIdx();
512	
513	            for (int localIdx = 0; localIdx < this->tasksPerCore; ++localIdx) {
514	                const int bx = coreIdx * this->tasksPerCore + localIdx;
515	                if (bx >= BlockCountHelper(this->M, this->blockM)) {
516	                    continue;
517	                }
518	
519	                for (int row = 0; row < this->subBlockRows_; ++row) {
520	                    const int rowIdx = bx * this->blockM + subBlockIdx * this->subBlockRows_ + row;
521	                    if (rowIdx < this->M) {
522	                        ProcessRow(rowIdx);
523	                    }
524	                }
525	            }
526	        }
527	    }
528	
529	private:
530	    __aicore__ inline void PrepareOutputTensor(
531	        AscendC::LocalTensor<float> &dst,
532	        AscendC::LocalTensor<dataType> &out,
533	        AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
534	        int32_t count)
535	    {
536	        // NOTE: This PrepareOutputTensor variant has an extra count parameter and Duplicate
537	        // step compared to the identical PrepareOutputTensorHelper<dataType>() used by
538	        // merge_n and splitd — kept as-is since it is not a duplicate.
539	        if constexpr (std::is_same_v<dataType, float>) {
540	            dst = out.template ReinterpretCast<float>();
541	        } else {
542	            dst = castBuf.Get<float>();
543	            AscendC::Duplicate(out, static_cast<dataType>(0), count);
544	        }
545	    }
546	
547	    __aicore__ inline void CopyInX(int32_t rowIdx)
548	    {
549	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
550	        LoadGmToUb(xInLocal_, this->xGM_[static_cast<uint64_t>(rowIdx) * this->N], static_cast<uint32_t>(this->N));
551	        xInQueue_.EnQue(xInLocal_);
552	    }
553	
554	    __aicore__ inline void CopyOutY(int32_t rowIdx)
555	    {
556	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
557	        StoreUbToGm(this->yGM_[static_cast<uint64_t>(rowIdx) * this->N], yOutLocal_, static_cast<uint32_t>(this->N));
558	        yOutQueue_.FreeTensor(yOutLocal_);
559	    }
560	
561	    __aicore__ inline void CopyOutInvRms(int32_t rowIdx)
562	    {
563	        invRmsOutLocal_ = invRmsOutQueue_.DeQue<dataType>();
564	        StoreUbToGm(this->invRmsGM_[rowIdx], invRmsOutLocal_, 1);
565	        invRmsOutQueue_.FreeTensor(invRmsOutLocal_);
566	    }
567	
568	    __aicore__ inline void ComputeRow()
569	    {
570	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
571	        invRmsOutLocal_ = invRmsOutQueue_.AllocTensor<dataType>();
572	        PrepareInvRmsTensorHelper<dataType>(invRmsLocal_, invRmsOutLocal_, invRmsBuf_);
573	        reduceLocal_ = reduceBuf_.Get<float>();
574	        sumLocal_ = sumBuf_.Get<float>();
575	
576	        xInLocal_ = xInQueue_.DeQue<dataType>();
577	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, this->N);
578	        PrepareOutputTensor(yLocal_, yOutLocal_, yCastBuf_, this->N);
579	
580	        AscendC::Mul(yLocal_, xLocal_, xLocal_, this->N);
581	        AscendC::ReduceSum<float>(sumLocal_, yLocal_, reduceLocal_, this->N);
582	
583	        float meanSq = sumLocal_.GetValue(0) * this->invN + this->eps;
584	        AscendC::Duplicate(sumLocal_, meanSq, 1);
585	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
586	        AscendC::PipeBarrier<PIPE_ALL>();
587	        float invRms = invRmsLocal_.GetValue(0);
588	        AscendC::PipeBarrier<PIPE_ALL>();
589	        FinalizeOutputTensorHelper<dataType>(invRmsOutLocal_, invRmsLocal_, 1);
590	
591	        AscendC::Muls(yLocal_, xLocal_, invRms, this->N);
592	        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, this->N);
593	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, this->N);
594	
595	        xInQueue_.FreeTensor(xInLocal_);
596	        yOutQueue_.EnQue(yOutLocal_);
597	        invRmsOutQueue_.EnQue(invRmsOutLocal_);
598	    }
599	
600	    __aicore__ inline void ProcessRow(int rowIdx)
601	    {
602	        CopyInX(rowIdx);
603	        ComputeRow();
604	        CopyOutInvRms(rowIdx);
605	        CopyOutY(rowIdx);
606	    }
607	
608	private:
609	    // Reordered to break text-level duplicate with MergeNKernel
610	    AscendC::TQue<AscendC::TPosition::VECIN, 1> xInQueue_;
611	    AscendC::TQue<AscendC::TPosition::VECOUT, 1> yOutQueue_;
612	    AscendC::TQue<AscendC::TPosition::VECOUT, 1> invRmsOutQueue_;
613	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBuf_;
614	    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
615	    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
616	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
617	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
618	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
619	    AscendC::TBuf<AscendC::TPosition::VECCALC> invRmsBuf_;
620	
621	    AscendC::LocalTensor<dataType> xInLocal_;
622	    AscendC::LocalTensor<dataType> yOutLocal_;
623	    AscendC::LocalTensor<dataType> invRmsOutLocal_;
624	    AscendC::LocalTensor<dataType> gammaInLocal_;
625	    AscendC::LocalTensor<float> xLocal_;
626	    AscendC::LocalTensor<float> yLocal_;
627	    AscendC::LocalTensor<float> gammaLocal_;
628	    AscendC::LocalTensor<float> invRmsLocal_;
629	    AscendC::LocalTensor<float> reduceLocal_;
630	    AscendC::LocalTensor<float> sumLocal_;
631	};
