687	private:
688	    static constexpr int kBlockN = 1024;
689	    static constexpr uint32_t kTileFloatBytes = kBlockN * sizeof(float);
690	
691	    __aicore__ inline int32_t NumTiles() const
692	    {
693	        return (this->N + kBlockN - 1) / kBlockN;
694	    }
695	
696	    __aicore__ inline int32_t GetValidN(int32_t colBase) const
697	    {
698	        return (colBase + kBlockN <= this->N) ? kBlockN : (this->N - colBase);
699	    }
700	
701	    __aicore__ inline void CopyInX(int32_t rowIdx, int32_t colBase, int32_t validN)
702	    {
703	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
704	        LoadGmToUb(xInLocal_, this->xGM_[static_cast<uint64_t>(rowIdx) * this->N + colBase], static_cast<uint32_t>(validN));
705	        xInQueue_.EnQue(xInLocal_);
706	    }
707	
708	    __aicore__ inline void CopyInGamma(int32_t colBase, int32_t validN)
709	    {
710	        gammaInLocal_ = gammaInQueue_.AllocTensor<dataType>();
711	        LoadGmToUb(gammaInLocal_, this->gammaGM_[colBase], static_cast<uint32_t>(validN));
712	        gammaInQueue_.EnQue(gammaInLocal_);
713	    }
714	
715	    __aicore__ inline void CopyOutY(int32_t rowIdx, int32_t colBase, int32_t validN)
716	    {
717	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
718	        StoreUbToGm(this->yGM_[static_cast<uint64_t>(rowIdx) * this->N + colBase], yOutLocal_, static_cast<uint32_t>(validN));
719	        yOutQueue_.FreeTensor(yOutLocal_);
720	    }
