722	    __aicore__ inline void CopyOutInvRms(int32_t rowIdx)
723	    {
724	        invRmsOutLocal_ = invRmsOutQueue_.DeQue<dataType>();
725	        StoreUbToGm(this->invRmsGM_[rowIdx], invRmsOutLocal_, 1);
726	        invRmsOutQueue_.FreeTensor(invRmsOutLocal_);
727	    }
