729	    __aicore__ inline float ComputeInvRms(int32_t rowIdx)
730	    {
731	        reduceLocal_ = reduceBuf_.Get<float>();
732	        sumLocal_ = sumBuf_.Get<float>();
733	        tempLocal_ = tempBuf_.Get<float>();
734	        invRmsOutLocal_ = invRmsOutQueue_.AllocTensor<dataType>();
735	        PrepareInvRmsTensorHelper<dataType>(invRmsLocal_, invRmsOutLocal_, invRmsBuf_);
736	        float sumSq = 0.0f;
737	
738	        for (int by = 0; by < NumTiles(); ++by) {
739	            const int colBase = by * kBlockN;
740	            const int validN = GetValidN(colBase);
741	
742	            CopyInX(rowIdx, colBase, validN);
743	
744	            xInLocal_ = xInQueue_.DeQue<dataType>();
745	            PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
746	            AscendC::Mul(tempLocal_, xLocal_, xLocal_, validN);
747	            AscendC::ReduceSum<float>(sumLocal_, tempLocal_, reduceLocal_, validN);
748	            sumSq += sumLocal_.GetValue(0);
749	            xInQueue_.FreeTensor(xInLocal_);
750	        }
751	
752	        AscendC::Duplicate(sumLocal_, sumSq * this->invN + this->eps, 1);
753	        AscendC::Rsqrt(invRmsLocal_, sumLocal_, 1);
754	        AscendC::PipeBarrier<PIPE_ALL>();
755	        float invRms = invRmsLocal_.GetValue(0);
756	        AscendC::PipeBarrier<PIPE_ALL>();
757	        FinalizeOutputTensorHelper<dataType>(invRmsOutLocal_, invRmsLocal_, 1);
758	
759	        invRmsOutQueue_.EnQue(invRmsOutLocal_);
760	        return invRms;
761	    }
762	
763	    __aicore__ inline void ComputeTile(float invRms, int32_t validN)
764	    {
765	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
766	        xInLocal_ = xInQueue_.DeQue<dataType>();
767	        gammaInLocal_ = gammaInQueue_.DeQue<dataType>();
768	        PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, validN);
769	        PrepareInputTensorHelper<dataType>(gammaLocal_, gammaInLocal_, gammaCastBuf_, validN);
770	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
771	        AscendC::Muls(yLocal_, xLocal_, invRms, validN);
772	        AscendC::Mul(yLocal_, yLocal_, gammaLocal_, validN);
773	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, validN);
774	        xInQueue_.FreeTensor(xInLocal_);
775	        gammaInQueue_.FreeTensor(gammaInLocal_);
776	        yOutQueue_.EnQue(yOutLocal_);
777	    }
778	
779	    __aicore__ inline void ProcessRow(int rowIdx)
780	    {
781	        float invRms = ComputeInvRms(rowIdx);
782	        CopyOutInvRms(rowIdx);
783	
784	        for (int by = 0; by < NumTiles(); ++by) {
785	            const int colBase = by * kBlockN;
786	            const int validN = GetValidN(colBase);
787	
788	            CopyInX(rowIdx, colBase, validN);
789	            CopyInGamma(colBase, validN);
790	            ComputeTile(invRms, validN);
791	            CopyOutY(rowIdx, colBase, validN);
792	        }
793	    }
