// AscendC Abs kernel — element-wise absolute value
// Supports float32, float16, bfloat16
// Pattern: CopyIn (DataCopyPad GM→UB) → Compute (Abs) → CopyOut (DataCopyPad UB→GM)

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;  // double buffer for copy-in/copy-out

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// Abs Kernel — single strategy, dtype dispatch at entry point
// =========================================================================

template <typename T>
class AbsKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t totalElements, int32_t usedCoreNum,
        int32_t tasksPerCore, int32_t tileSize)
    {
        this->totalElements = totalElements;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->tileSize = tileSize;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), static_cast<uint64_t>(totalElements));
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), static_cast<uint64_t>(totalElements));

        if (ASCEND_IS_AIV) {
            pipe.InitBuffer(inQueue_, BUFFER_NUM, tileSize * sizeof(T));
            pipe.InitBuffer(outQueue_, BUFFER_NUM, tileSize * sizeof(T));
        }
    }

    __aicore__ inline void Process()
    {
        if (ASCEND_IS_AIV) {
            int coreIdx = AscendC::GetBlockIdx();
            int globalCoreNum = AscendC::GetBlockNum();

            // Compute global task range for this core
            int globalTaskStart = coreIdx * tasksPerCore;
            int globalTaskEnd = globalTaskStart + tasksPerCore;
            int totalTasks = CeilDivU32(static_cast<uint32_t>(totalElements), static_cast<uint32_t>(tileSize));

            for (int taskIdx = globalTaskStart; taskIdx < globalTaskEnd && taskIdx < totalTasks; ++taskIdx) {
                int elementOffset = taskIdx * tileSize;
                int validCount = (elementOffset + tileSize <= totalElements) ? tileSize : (totalElements - elementOffset);

                CopyIn(elementOffset, validCount);
                Compute(validCount);
                CopyOut(elementOffset, validCount);
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t offset, int32_t count)
    {
        inLocal_ = inQueue_.AllocTensor<T>();
        LoadGmToUb(inLocal_, xGM_[static_cast<uint64_t>(offset)], static_cast<uint32_t>(count));
        inQueue_.EnQue(inLocal_);
    }

    __aicore__ inline void Compute(int32_t count)
    {
        inLocal_ = inQueue_.DeQue<T>();
        outLocal_ = outQueue_.AllocTensor<T>();
        AscendC::Abs(outLocal_, inLocal_, count);
        AscendC::PipeBarrier<PIPE_V>();
        inQueue_.FreeTensor(inLocal_);
        outQueue_.EnQue(outLocal_);
    }

    __aicore__ inline void CopyOut(int32_t offset, int32_t count)
    {
        outLocal_ = outQueue_.DeQue<T>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(offset)], outLocal_, static_cast<uint32_t>(count));
        outQueue_.FreeTensor(outLocal_);
    }

private:
    int32_t totalElements = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    int32_t tileSize = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<T> xGM_;
    AscendC::GlobalTensor<T> yGM_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue_;
    AscendC::LocalTensor<T> inLocal_;
    AscendC::LocalTensor<T> outLocal_;
};

// =========================================================================
// dtype dispatch helper
// =========================================================================

template <template <typename> class Kernel, typename... ExtraArgs>
__aicore__ inline void DispatchAbs(
    GM_ADDR x, GM_ADDR y,
    int32_t totalElements, int32_t usedCoreNum,
    int32_t tasksPerCore, int32_t tileSize,
    int64_t dtypeFlag, ExtraArgs... extraArgs)
{
    if (dtypeFlag == 0) {
        Kernel<float> kernel;
        kernel.Init(x, y, totalElements, usedCoreNum, tasksPerCore, tileSize, extraArgs...);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(x, y, totalElements, usedCoreNum, tasksPerCore, tileSize, extraArgs...);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(x, y, totalElements, usedCoreNum, tasksPerCore, tileSize, extraArgs...);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry point — single __global__, dtype dispatch inside
// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
// =========================================================================

extern "C" __global__ __aicore__ void abs_kernel(
    GM_ADDR x, GM_ADDR y,
    int32_t totalElements, int32_t usedCoreNum,
    int32_t tasksPerCore, int32_t tileSize,
    int64_t dtypeFlag)
{
    DispatchAbs<AbsKernel>(x, y, totalElements, usedCoreNum, tasksPerCore, tileSize, dtypeFlag);
}
