// Abs op_host — tiling calculation + EXEC_KERNEL_CMD launch
// Supports float32, float16 directly through AscendC kernel.
// bfloat16 is handled via host-side float32 conversion (DAV_2201 kernel
// does not support bfloat16_t type natively).

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_abs_kernel.h"

namespace ascend_kernel {

at::Tensor abs(const at::Tensor &x)
{
    TORCH_CHECK(
        x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
            x.scalar_type() == at::kBFloat16,
        "x must be float16, float32, or bfloat16");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    // bfloat16 handling: convert to float32, invoke kernel, convert back.
    // DAV_2201 (Ascend910B) AscendC compiler does not support bfloat16_t
    // as a kernel template type; host-side conversion is the reliable path.
    if (x.scalar_type() == at::kBFloat16) {
        at::Tensor x_fp32 = x.to(at::kFloat);
        at::Tensor y_fp32 = abs(x_fp32);
        return y_fp32.to(at::kBFloat16);
    }

    // Compute total elements (flat size)
    int64_t totalElements64 = x.numel();
    TORCH_CHECK(totalElements64 <= static_cast<int64_t>(INT32_MAX),
        "total elements exceeds int32 range");
    int32_t totalElements = static_cast<int32_t>(totalElements64);

    // Empty output tensor, same shape and dtype
    at::Tensor y = at::empty_like(x);

    // dtype flag: 0=fp32, 1=fp16 (bf16 handled above)
    int64_t dtypeFlag = 0;
    if (x.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    }

    // Get core count
    int32_t coreNum = static_cast<int32_t>(
        platform_ascendc::PlatformAscendCManager::GetInstance()->GetCoreNumAicore());
    if (coreNum <= 0) {
        coreNum = 1;
    }

    // Tile size: based on UB capacity
    // DAV_2201 (Ascend910B) UB = 192KB
    // tileSize = UB / sizeof(dtype). Use conservative value fitting UB
    // even with double buffering (2 * tileSize).
    int32_t elemSize = static_cast<int32_t>(x.element_size());
    constexpr int32_t UB_CAPACITY = 192 * 1024;
    int32_t tileSize = (UB_CAPACITY / elemSize) / 2;
    // Round down to multiple of 256 for alignment
    tileSize = (tileSize / 256) * 256;
    if (tileSize < 256) { tileSize = 256; }

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int32_t usedCoreNum = std::min<int32_t>(coreNum, std::max<int32_t>(1, totalElements));
    int32_t tasksPerCore = (totalElements + usedCoreNum - 1) / usedCoreNum;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(abs_kernel, blockDim,
                    x, y,
                    totalElements, usedCoreNum, tasksPerCore, tileSize,
                    dtypeFlag);

    return y;
}

}  // namespace ascend_kernel
